namespace Gunt.ControlCenter {public static class App {
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string c,string t);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint m,IntPtr wp,IntPtr lp);[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int c);[DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [STAThread]public static void Main(string[] args){string root=args.Length>0?args[0]:Directory.GetParent(AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\')).FullName;string page=args.Length>1?args[1]:"overview";if(page=="automation-event"){try{if(args.Length>2)new Gunt.ControlCenter.Services.DesktopService(root).RunAutomationRule(args[2]);}catch(Exception e){File.AppendAllText(Path.Combine(root,"logs","automation-errors.log"),DateTimeOffset.Now+" "+e.Message+Environment.NewLine);}return;}
 if(page=="launchpad"){var launcherService=new Gunt.ControlCenter.Services.DesktopService(root);bool fresh;using(var launcherMutex=new Mutex(true,launcherService.ScopedMutex("Launchpad"),out fresh)){if(!fresh){var hwnd=GuntLaunchpadWindow.Find(root);PostMessage(hwnd,0x8006,IntPtr.Zero,GetForegroundWindow());return;}SetProcessDpiAwarenessContext(new IntPtr(-4));var launcherApp=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};launcherApp.DispatcherUnhandledException+=delegate(object sender,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){Directory.CreateDirectory(Path.Combine(root,"logs"));File.AppendAllText(Path.Combine(root,"logs","launchpad-errors.log"),DateTimeOffset.Now+" "+e.Exception+Environment.NewLine);e.Handled=true;};try{launcherApp.Run(new LaunchpadWindow(root));}catch(Exception error){Directory.CreateDirectory(Path.Combine(root,"logs"));File.AppendAllText(Path.Combine(root,"logs","launchpad-errors.log"),DateTimeOffset.Now+" "+error+Environment.NewLine);MessageBox.Show("Launchpad를 열지 못했습니다. 설정 원본은 보존했습니다.\n"+error.Message,"GUNT Launchpad");}}return;}
 if(page=="quick-panel"||page=="palette"){bool popupCreated;using(var popupMutex=new Mutex(true,"Local\\GUNTDeveloperPopup-"+page,out popupCreated)){if(!popupCreated){var popup=FindWindow(null,page=="palette"?"GUnT_0x9 명령 팔레트":"GUnT_0x9 빠른 패널");ShowWindow(popup,9);SetForegroundWindow(popup);return;}SetProcessDpiAwarenessContext(new IntPtr(-4));var popupApp=new Application();popupApp.Run(new DeveloperPopup(root,page=="palette"));}return;}
 bool created;using(var mutex=new Mutex(true,"Local\\GUNTControlCenterV24",out created)){
  if(!created){var h=FindWindow(null,"GUnT_0x9 Desktop");if(h==IntPtr.Zero)h=FindWindow(null,"GUNT 제어 센터");GuntConfiguration.Atomic(root,Path.Combine(root,"state","control-center-open.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new {page=page}),false);ShowWindow(h,9);SetForegroundWindow(h);PostMessage(h,0x8004,IntPtr.Zero,IntPtr.Zero);return;}
  SetProcessDpiAwarenessContext(new IntPtr(-4));AppContext.SetSwitch("Switch.System.Windows.DoNotScaleForDpiChanges",false);AppContext.SetSwitch("Switch.System.Windows.DoNotUsePresentationDpiCapabilityTier2OrGreater",false);
  var app=new Application();app.DispatcherUnhandledException+=delegate(object sender,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){File.AppendAllText(Path.Combine(root,"logs","control-center-errors.log"),DateTimeOffset.Now+" "+e.Exception+Environment.NewLine);MessageBox.Show("제어 센터 처리 중 오류가 발생했습니다.\n"+e.Exception.Message,"GUnT_0x9 Desktop");e.Handled=true;};app.Run(new MainWindow(root,page));
 }}
